6: // os.environ["X"], os.environ.get("X"), os.getenv("X")
7: const ENV_RE = /os\.environ\[\s*["']([A-Za-z_]\w*)["']\s*\]|os\.(?:getenv|environ\.get)\(\s*["']([A-Za-z_]\w*)["']/g;
8: 
9: // Write small.toml from detection. Returns false when the entry could not be determined.
10: function init(dir, { force = false } = {}) {
11:   const tomlPath = path.join(dir, 'small.toml');
12:   if (fs.existsSync(tomlPath) && !force) {
13:     console.log('small.toml already exists — use --force to overwrite');
14:     return true;
15:   }
16: 
17:   let app = null;
18:   try {
19:     app = detect(dir);
20:   } catch {}
21:   const name = (app && app.name) || path.basename(dir).toLowerCase().replace(/[^a-z0-9-]/g, '-');
22:   const required = [];
23:   if (app) {
24:     const source = fs.readFileSync(path.join(dir, app.entry), 'utf8');
25:     for (const m of source.matchAll(ENV_RE)) {
26:       const v = m[1] || m[2];
27:       if (!required.includes(v)) required.push(v);
28:     }
29:   }
30:   const hasReqs = fs.existsSync(path.join(dir, 'requirements.txt'));
31: 
32:   const lines = [`name = "${name}"`];
33:   lines.push(app ? `entry = "${app.entry}"` : 'entry = ""                     # fill in: your app\'s main .py file');
34:   lines.push(`framework = "${app ? app.framework : ''}"`);
35:   if (hasReqs) lines.push('', '[deps]', 'file = "requirements.txt"');
36:   lines.push('', '[secrets]');
37:   lines.push(required.length ? `required = [${required.map((n) => `"${n}"`).join(', ')}]` : 'required = []                  # env vars this app reads — fill in');
38:   lines.push('', '[access]', 'visibility = "domain"', '');
39:   fs.writeFileSync(tomlPath, lines.join('\n'));
40: 
41:   console.log(`✓ name: ${name}`);
42:   if (app) console.log(`✓ entry: ${app.entry} (${app.framework})`);
43:   if (hasReqs) console.log('✓ deps: requirements.txt');
44:   if (required.length) console.log(`✓ secrets: ${required.join(', ')} (read by ${app.entry})`);
45:   console.log('✓ visibility: domain');
46:   console.log('✓ wrote small.toml');
47:   if (!app) console.log('✗ could not find the entry file — fill in entry = "your-app.py" in small.toml');
48:   return !!app;
49: }
